const D = { jitter:.5, scale:1, density:.5, speed:1, energy:.6, hue:40, x:.5, y:.5, style:'pencil', act:'draw', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const u = Math.min(width, height);
const st = P.style;
const clamp = (v,a,b)=> v<a?a:(v>b?b:v);
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };

// --- paper / ground backdrop (cached, style-dependent) ---
const bgKey = width+'x'+height+'|'+P.seed+'|'+st+'|'+Math.round(P.hue);
if (!S.paper || S.bgKey !== bgKey){
  S.bgKey = bgKey;
  const g = createGraphics(width,height);
  g.colorMode(HSB,360,100,100,100);
  g.noStroke();
  let base, floor;
  if (st==='blueprint'){ base=[210,62,42]; floor=[210,55,34]; }
  else if (st==='chalk'){ base=[210,16,13]; floor=[160,20,10]; }
  else if (st==='neon'){ base=[245,40,7]; floor=[260,45,5]; }
  else if (st==='crayon'){ base=[45,12,88]; floor=[95,26,74]; }
  else { base=[42,11,87]; floor=[82,20,76]; } // pencil / ink -> warm cream paper + grassy ground
  g.fill(base[0],base[1],base[2]); g.rect(0,0,width,height);
  g.fill(floor[0],floor[1],floor[2]); g.rect(0,height*0.66,width,height*0.34);
  // seeded grain
  const grains = 900;
  for (let i=0;i<grains;i++){
    const gx=fr(i*2+11)*width, gy=fr(i*2+12)*height;
    const dk = st==='blueprint'||st==='chalk'||st==='neon';
    g.fill(dk?[0,0,100][0]:0,0, dk?100:0, dk?4:5);
    g.rect(gx,gy,1,1);
  }
  S.paper=g;
}
image(S.paper,0,0);

// --- build the scene stroke list (seeded positions), cached ---
const scKey = P.seed+'|'+P.density.toFixed(2)+'|'+P.scale.toFixed(2);
if (!S.SK || S.scKey !== scKey){
  S.scKey = scKey;
  const SK=[]; let ord=0;
  const seg=(pts,w,ch,fig)=>{ SK.push({pts,w,o:ord,ch:ch==null?-1:ch,fig:!!fig}); ord+=0.06; };
  const ring=(cx,cy,r,ry,n,w,ch)=>{ const a=[]; for(let k=0;k<=n;k++){const th=k/n*TWO_PI; a.push([cx+Math.cos(th)*r, cy+Math.sin(th)*(ry||r)]);} SK.push({pts:a,w,o:ord,ch:ch==null?-1:ch,close:true}); ord+=0.06; };
  // hills / horizon
  const hpts=[]; const hn=14; const hy=0.64+(fr(3)-0.5)*0.03;
  for(let k=0;k<=hn;k++){ const x=k/hn; hpts.push([x, hy - Math.max(0,Math.sin(x*3.1+fr(7)*6))*0.09*(0.6+fr(k+20)*0.5)]); }
  seg(hpts,0.006,-1);
  // sun (accent hue) up-right, remembered center for live rays
  const sx=0.78+(fr(5)-0.5)*0.06, sy=0.19+(fr(6)-0.5)*0.05, sr=0.085+fr(9)*0.02;
  S.sun=[sx,sy,sr]; ring(sx,sy,sr,sr,16,0.006,P.hue);
  // house
  const hx=0.20+fr(2)*0.06, hw=0.18*(0.9+fr(4)*0.3), hh=0.16, by=hy;
  seg([[hx,by],[hx,by-hh],[hx+hw,by-hh],[hx+hw,by],[hx,by]],0.006,-1);        // body
  seg([[hx-0.02,by-hh],[hx+hw*0.5,by-hh-0.11],[hx+hw+0.02,by-hh]],0.007,(P.hue+20)%360); // roof
  seg([[hx+hw*0.55,by],[hx+hw*0.55,by-0.07],[hx+hw*0.78,by-0.07],[hx+hw*0.78,by]],0.005,-1); // door
  ring(hx+hw*0.25,by-hh*0.62,0.022,0.022,10,0.005,(P.hue+180)%360); // window
  // tree
  const tx=0.56+fr(8)*0.05, ty=hy;
  seg([[tx,ty],[tx,ty-0.13]],0.008,25);
  ring(tx,ty-0.17,0.06,0.055,12,0.006,120);
  // stick figures (density adds more)
  const nf = 1 + Math.round(P.density*3);
  for (let f=0; f<nf; f++){
    const fxc=0.32+f*0.13+fr(f*4+30)*0.03, fyc=hy, sc=0.085*(0.85+fr(f+40)*0.3);
    ring(fxc,fyc-sc*2.1,sc*0.42,sc*0.42,10,0.005,-1,true);              // head
    seg([[fxc,fyc-sc*1.7],[fxc,fyc-sc*0.7]],0.006,-1,true);             // torso
    seg([[fxc-sc*0.6,fyc-sc*1.35],[fxc,fyc-sc*1.5],[fxc+sc*0.6,fyc-sc*1.1]],0.005,-1,true); // arms
    seg([[fxc-sc*0.5,fyc],[fxc,fyc-sc*0.7],[fxc+sc*0.5,fyc]],0.005,-1,true);                // legs
  }
  // clouds
  const nc = 2 + Math.round(P.density*2);
  for (let c=0;c<nc;c++){ const cx=0.12+fr(c*5+50)*0.6, cy=0.12+fr(c*5+51)*0.14; ring(cx,cy,0.06,0.032,12,0.005,-1); }
  S.SK=SK; S.ordMax=ord;
}

// --- draw progress (self-drawing dramaturgy) + boiling line ---
const period = 22;
let prog;
if (P.act==='loop'){ const ph=(K.t%40)/40; prog = ph<0.72? (ph/0.72)*(S.ordMax+0.2) : (S.ordMax+0.2); }
else { prog = Math.min(S.ordMax+0.2, (K.t/period)*(S.ordMax+0.2)); }
const jw = P.jitter*u*0.026;                 // wobble amplitude
const boil = 2.1*P.speed;                    // real-time boiling rate (never re-phases)
const windy = (P.act==='windy');
const fieldW=1.4*u*P.scale, fieldH=0.95*u*P.scale;
const ox=P.x*width-fieldW*0.5, oy=P.y*height-fieldH*0.5;
const M=(nx,ny)=>[ox+nx*fieldW, oy+ny*fieldH];

const colOf = (h)=>{
  if (st==='ink') return [0,0,10];
  if (st==='blueprint') return [200,8,99];
  if (st==='chalk') return h<0?[0,0,92]:[h,32,94];
  if (st==='neon') return h<0?[P.hue,88,100]:[h,90,100];
  if (st==='crayon') return h<0?[28,55,55]:[h,72,80];
  return h<0?[35,10,24]:[h,26,38]; // pencil graphite w/ faint accent tint
};

let li=0;
for (const s of S.SK){
  const local = clamp((prog - s.o)/0.14, 0, 1);
  if (local<=0){ li++; continue; }
  const col = colOf(s.ch);
  const alpha = (st==='pencil'?62:88) * (0.35+0.65*local);
  const nseg = s.pts.length;
  const shown = s.close? nseg : Math.max(2, Math.floor(1+local*(nseg-1)));
  strokeWeight(Math.max(0.8, s.w*u*(0.9+P.energy*0.5)*(st==='ink'?1.5:1)));
  stroke(col[0],col[1],col[2],alpha); noFill();
  if (st==='neon'){ drawingContext.shadowBlur=10; drawingContext.shadowColor='hsl('+col[0]+',95%,60%)'; }
  const figBob = s.fig? -Math.abs(Math.sin(K.beat*P.speed*PI))*u*0.02 - (K.pulse*u*0.012) : 0;
  const figSway = s.fig? Math.sin(K.beat*P.speed*PI*0.5)*u*0.01 : 0;
  beginShape();
  const kmax = s.close? nseg : shown;
  for (let k=0;k<kmax;k++){
    const bp=s.pts[k];
    const id=(li*97+k)*1.7;
    const wob = jw + A.mid*u*0.006;
    const sway = windy? Math.sin(K.t*1.3 + bp[1]*4)*u*0.012*(1-bp[1]) : 0;
    const dx = Math.sin(id*1.3 + K.t*boil)*wob + sway + figSway;
    const dy = Math.cos(id*1.7 + K.t*boil*1.08)*wob + figBob;
    const sc=M(bp[0],bp[1]);
    curveVertex(sc[0]+dx, sc[1]+dy);
  }
  endShape(s.close?CLOSE:undefined);
  if (st==='neon'){ drawingContext.shadowBlur=0; }
  li++;
}

// --- live sun rays (rotate slowly; revealed with the sun) ---
if (S.sun && prog>0.06){
  const [sxn,syn,srn]=S.sun; const sc=M(sxn,syn); const rr=srn*fieldW;
  const rc=colOf(P.hue);
  strokeWeight(Math.max(1,u*0.004)); stroke(rc[0],rc[1],rc[2], 70*clamp((prog-0.06)/0.14,0,1));
  if (st==='neon'){ drawingContext.shadowBlur=12; drawingContext.shadowColor='hsl('+rc[0]+',95%,60%)'; }
  for (let k=0;k<9;k++){
    const th=k/9*TWO_PI + K.t*0.18;
    const jr=1+Math.sin(K.t*boil+k)*0.06;
    line(sc[0]+Math.cos(th)*rr*1.35, sc[1]+Math.sin(th)*rr*1.35, sc[0]+Math.cos(th)*rr*(2.0*jr), sc[1]+Math.sin(th)*rr*(2.0*jr));
  }
  if (st==='neon'){ drawingContext.shadowBlur=0; }
}
